import Foundation

/// XPC service run by launchd (LaunchAgent) for the token extension.
final class HelperService: NSObject, NSXPCListenerDelegate, HelperProtocol {
	let session: PKCS11Session

	init(modulePath: String) {
		session = PKCS11Session(modulePath: modulePath)
	}

	func listener(_ listener: NSXPCListener, shouldAcceptNewConnection connection: NSXPCConnection) -> Bool {
		// Only our own token extension (see BuildInfo.swift, generated by scripts/build.sh) may ask for signatures.
		connection.setCodeSigningRequirement(tokenCodeRequirement)
		connection.exportedInterface = NSXPCInterface(with: HelperProtocol.self)
		connection.exportedObject = self
		connection.resume()
		return true
	}

	func signDigestInfo(_ digestInfo: Data, keyID: String, reply: @escaping (Data?, String?) -> Void) {
		guard let id = data(fromHex: keyID) else {
			reply(nil, "bad key id")
			return
		}
		do {
			let signature = try session.sign(digestInfo: digestInfo, keyID: id)
			log("signed \(digestInfo.count) bytes")
			reply(signature, nil)
		} catch {
			log("sign failed: \(error)")
			reply(nil, "\(error)")
		}
	}
}

func runHelper(modulePath: String) -> Never {
	let service = HelperService(modulePath: modulePath)
	let listener = NSXPCListener(machServiceName: Identifiers.helperService)
	listener.delegate = service
	listener.resume()
	log("helper listening on \(Identifiers.helperService), module \(modulePath)")

	// launchd sends SIGTERM on bootout/logout; finalize so the module sees a clean disconnect.
	signal(SIGTERM, SIG_IGN)
	let termination = DispatchSource.makeSignalSource(signal: SIGTERM, queue: .main)
	termination.setEventHandler {
		log("stopping")
		service.session.shutdown()
		exit(0)
	}
	termination.resume()

	RunLoop.main.run()
	exit(0)
}
